grid = [[4]*19 for _ in range(16)]
markers = [(2,5),(2,14),(3,1),(3,10),(5,17),(7,3),(7,13),(8,10),(10,6),(12,16),(13,10),(14,7)]
# Seed motif remains at rows 12-14, cols 2-4.
seed = {(12,2):8,(12,3):8,(12,4):2,(13,3):9,(13,4):2,(14,3):9,(14,4):9}
for (r,c),v in seed.items(): grid[r][c]=v
motif = {(-1,-1):8,(-1,0):8,(-1,1):2,(0,0):9,(0,1):2,(1,0):9,(1,1):9}
for r,c in markers:
    for (dr,dc),v in motif.items():
        rr,cc=r+dr,c+dc
        if 0 <= rr < 16 and 0 <= cc < 19:
            # Motif marks overlay the background and replace the marker at its center.
            grid[rr][cc]=v
import json
print(json.dumps(grid,separators=(',',':')))
